[CmdletBinding()]param([int]$Port=40980)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot '..\common\SpikeProofRuntime.psm1') -Force;$c=Get-SpikeProofConfig;$runtime=$null;$completed=$false
try{$runtime=Start-OpencodeProofRuntime -Name 'rust-client-proof' -Port $Port -Permission @{'*'='deny'} -ToolFiles @((Join-Path $PSScriptRoot 'tools\bash.ts'));cargo build -p ollama-cowork-opencode-client --example probe --locked;if($LASTEXITCODE-ne0){throw 'Rust client probe build failed'};$exe=Join-Path $c.CargoTargetRoot 'examples\probe.exe';$oldUrl=$env:SPIKE_OPENCODE_URL;$oldAuth=$env:SPIKE_OPENCODE_AUTH;try{$env:SPIKE_OPENCODE_URL=$runtime.BaseUrl;$env:SPIKE_OPENCODE_AUTH=$runtime.Authorization;$output=&$exe;if($LASTEXITCODE-ne0){throw 'Rust client probe failed'}}finally{$env:SPIKE_OPENCODE_URL=$oldUrl;$env:SPIKE_OPENCODE_AUTH=$oldAuth};$result=$output|ConvertFrom-Json;if(-not$result.passed-or-not$result.healthy){throw 'Rust client result failed'}; [IO.File]::WriteAllText((Join-Path $c.EvidenceRoot 'spike-001-rust-opencode-client-proof-result.json'),($result|ConvertTo-Json -Depth 8));$result|Format-List;$completed=$true}finally{if($runtime){Stop-OpencodeProofRuntime $runtime $completed 'rust-opencode-client-failure-logs'}}
